login.fast_script_login:
(username, password) => {
  const userEl = document.querySelector("input[placeholder*='điện thoại'], input[placeholder*='email'], input[placeholder*='username']");
  const passEl = document.querySelector("input[type='password']");
  const submitBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Đăng nhập'));
  if (userEl && passEl) {
    userEl.value = username;
    userEl.dispatchEvent(new Event('input', { bubbles: true }));
    passEl.value = password;
    passEl.dispatchEvent(new Event('input', { bubbles: true }));
    if (submitBtn) submitBtn.click();
    return true;
  }
  return false;
}

classroom_exams.fast_script_one_shot_check_all:
() => {
  Array.from(document.querySelectorAll('button')).filter(b => b.textContent.trim() === 'Xem thêm').forEach(b => b.click());
  const uncompletedExams = [];
  Array.from(document.querySelectorAll("a[href*='/vi/de-thi/']")).forEach(link => {
    if (link.innerText.includes('Chưa thi')) {
      const lines = link.innerText.split('\n').map(s => s.trim()).filter(Boolean);
      const codeMatch = link.href.match(/\/vi\/de-thi\/([a-zA-Z0-9]+)/);
      uncompletedExams.push({
        title: lines[0] || 'Đề thi',
        code: codeMatch ? codeMatch[1] : '',
        deadline: lines.find(l => l.includes('Thời gian') || l.includes('Thi trước')) || 'Không thời hạn',
        url: link.href
      });
    }
  });
  const uncompletedAssignments = [];
  Array.from(document.querySelectorAll("a[href*='/vi/bai-tap/']")).forEach(link => {
    if (link.innerText.includes('Chưa nộp')) {
      const lines = link.innerText.split('\n').map(s => s.trim()).filter(Boolean);
      uncompletedAssignments.push({
        title: lines.find(l => l !== 'Chưa nộp' && l.length > 2) || 'Bài tập',
        deadline: lines.find(l => l.includes('Hạn cuối') || l.includes('Bắt đầu nộp')) || '',
        url: link.href
      });
    }
  });
  return { uncompletedExams, uncompletedAssignments };
}

