take_test.fast_script_fill_answers:
(abcdAnswers, tfAnswers) => {
  const allButtons = Array.from(document.querySelectorAll('button'));
  const abcdButtons = allButtons.filter(b => ['A', 'B', 'C', 'D'].includes(b.textContent.trim()));
  const tfButtons = allButtons.filter(b => ['Đúng', 'Sai'].includes(b.textContent.trim()));

  let abcdCount = 0;
  for (let q = 0; q < abcdAnswers.length; q++) {
    const targetChar = abcdAnswers[q];
    const qButtons = abcdButtons.slice(q * 4, q * 4 + 4);
    const btn = qButtons.find(b => b.textContent.trim() === targetChar);
    if (btn) { btn.click(); abcdCount++; }
  }

  let tfCount = 0;
  for (let item = 0; item < tfAnswers.length; item++) {
    const targetChoice = tfAnswers[item];
    const itemButtons = tfButtons.slice(item * 2, item * 2 + 2);
    const btn = itemButtons.find(b => b.textContent.trim() === targetChoice);
    if (btn) { btn.click(); tfCount++; }
  }

  return {
    abcdFilled: abcdCount,
    tfFilled: tfCount,
    totalSelected: document.querySelectorAll('.selected-answer').length
  };
}
